// Optional — value may or may not exist (no null pointer crashes)
var maybeInt: Int? = 42
var nothing: String? = nil

// Forced unwrap (dangerous — crashes if nil!)
let val = maybeInt!   // only use when you're 100% sure

// Optional binding — safe
if let value = maybeInt {
    print("Got: \(value)")
} else {
    print("Nothing")
}

// Shorthand (Swift 5.7+)
if let maybeInt {   // binds to same name
    print(maybeInt)
}

// guard let — early exit pattern (preferred in functions)
func process(value: Int?) {
    guard let v = value else {
        print("No value")
        return   // must exit scope here
    }
    print("Value: \(v)")  // v is available from here
}

// Nil coalescing — default value
let result = maybeInt ?? 0   // 42 or 0 if nil

// Optional chaining — safe access (returns Optional)
let str: String? = "Hello"
let len = str?.count         // Int? = Optional(5)
let upper = str?.uppercased()  // Optional("HELLO")

// Multiple optional chaining
let city = user?.address?.city   // nil if any is nil
