// if/else
if x > 0 {
    print("positive")
} else if x == 0 {
    print("zero")
} else {
    print("negative")
}
let label = x > 0 ? "positive" : "non-positive"

// switch — must be exhaustive, no fallthrough by default!
switch day {
case "Monday", "Tuesday", "Wednesday", "Thursday", "Friday":
    print("Weekday")
case "Saturday", "Sunday":
    print("Weekend")
default:
    print("Unknown")
}

// switch with ranges and where
switch score {
case 90...100:    print("A")
case 80..<90:     print("B")
case let n where n < 60: print("Fail: \(n)")
default:          print("C or D")
}

// for-in
for i in 1...5 { print(i) }
for i in 0..<5 { print(i) }   // half-open range
for item in array { print(item) }
for (index, value) in array.enumerated() {
    print("\(index): \(value)")
}
for (key, value) in dict { print("\(key): \(value)") }
for i in 1...20 where i % 3 == 0 { print(i) }  // where clause

// repeat-while (do-while)
repeat {
    count += 1
} while count < 5

// defer — runs when scope exits (even on early return!)
defer { print("cleanup") }
