// Struct — VALUE type (copied, on stack)
struct Point {
    var x: Double
    var y: Double

    init(_ x: Double, _ y: Double) { self.x = x; self.y = y }

    func distance(to other: Point) -> Double {
        let dx = x - other.x; let dy = y - other.y
        return (dx*dx + dy*dy).squareRoot()
    }
    mutating func translate(by dx: Double, _ dy: Double) {
        x += dx; y += dy  // must be mutating to change properties
    }
    static let origin = Point(0, 0)
}

// Class — REFERENCE type (shared, on heap, supports inheritance)
class Animal {
    let name: String
    init(name: String) { self.name = name }
    deinit { print("\(name) deinitialized") }  // like destructor
    func speak() -> String { "\(name) speaks" }
}

class Dog: Animal {
    let breed: String
    init(name: String, breed: String) {
        self.breed = breed
        super.init(name: name)  // must call super.init
    }
    override func speak() -> String { super.speak() + "!" }
}

// Enum with associated values
enum Shape {
    case circle(radius: Double)
    case rectangle(width: Double, height: Double)

    var area: Double {
        switch self {
        case .circle(let r):          return .pi * r * r
        case .rectangle(let w, let h): return w * h
        }
    }
}

let c = Shape.circle(radius: 5)
print(c.area)  // 78.54

// Enum with raw values
enum Planet: Int, CaseIterable {
    case mercury = 1, venus, earth, mars
}
Planet(rawValue: 3)   // .earth
Planet.allCases       // all cases
