import Foundation

// async function — can suspend without blocking a thread
func fetchUser(id: Int) async throws -> String {
    try await Task.sleep(nanoseconds: 1_000_000_000)  // 1 second
    return "User \(id)"
}

// await — call async functions
Task {
    do {
        let user = try await fetchUser(id: 1)
        print(user)
    } catch {
        print("Error: \(error)")
    }
}

// async let — parallel execution!
Task {
    async let user  = fetchUser(id: 1)
    async let posts = fetchPosts(userId: 1)
    let (u, p) = try await (user, posts)  // both run concurrently
    print(u, p)
}

// TaskGroup — dynamic parallelism
Task {
    await withTaskGroup(of: String.self) { group in
        for i in 1...5 {
            group.addTask { await fetchUser(id: i) }
        }
        for await result in group {
            print(result)
        }
    }
}

// Actor — thread-safe reference type
actor BankAccount {
    private var balance: Double = 0

    func deposit(_ amount: Double) { balance += amount }
    func withdraw(_ amount: Double) throws -> Double {
        guard balance >= amount else { throw BankError.insufficientFunds }
        balance -= amount
        return amount
    }
    var currentBalance: Double { balance }
}

let account = BankAccount()
await account.deposit(100)
let amount = try await account.withdraw(50)

// @MainActor — ensure runs on main thread (UI updates)
@MainActor
func updateUI(with text: String) {
    label.text = text
}
